using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
namespace PZ3D {
 static class UiUpdateTests {
  static void Check(bool result,string text){if(!result)throw new Exception("FAIL: "+text);Console.WriteLine("PASS: "+text);}
  public static void Run(){
   Check(WorkshopWorker.AllowItem(3810637496UL),"optional Chinese patch can use isolated official workshop download");
   var chinese=typeof(Engine).Assembly.GetType("PZ3D.ChinesePatch");Check(chinese!=null,"game-menu Chinese patch supports reversible install");
   var type=typeof(Engine).Assembly.GetType("PZ3D.InstallWorkflow");Check(type!=null,"install automatically coordinates missing workshop downloads");
   foreach(bool selected in new[]{true,false}){string root=Path.Combine(LauncherTestPaths.Root,"orange-install-flow-"+Guid.NewGuid().ToString("N"));string game=Path.Combine(root,"steamapps","common","ProjectZomboid");Directory.CreateDirectory(game);var e=new Engine(game,Path.Combine(root,"user"),Path.Combine(root,"data"),true);e.PresetSource=Path.Combine(root,"no-presets");string before="{\"vmArgs\":[\"-Xmx28672m\"]}";File.WriteAllText(e.Config,before);Func<ulong[],Dictionary<ulong,string>> fetch=ids=>{Check(File.ReadAllText(e.Config)==before,"download occurs before game configuration mutation");Check(selected?ids.Contains(3810302175UL):!ids.Contains(3810302175UL),"download request respects explicit model pack selection");var paths=new Dictionary<ulong,string>();foreach(ulong id in ids){string p=Path.Combine(e.Workshop,id.ToString());Directory.CreateDirectory(p);paths[id]=p;if(id==3619862853UL){string libs=Path.Combine(p,"mods","ZombieBuddy","libs");Directory.CreateDirectory(libs);File.WriteAllText(Path.Combine(libs,"ZombieBuddy.jar"),"fixture");File.WriteAllText(Path.Combine(libs,"zbNative.dll"),"fixture");}if(id==3809306528UL){File.WriteAllText(Path.Combine(p,"mod.info"),"id=Viewpoint\n");}}return paths;};type.GetMethod("Enable").Invoke(null,new object[]{e,selected,fetch});Check(e.Enabled&&File.Exists(Path.Combine(game,"zbNative.dll")),"downloaded dependencies are physically deployed by install");Check(File.ReadAllText(e.Mods).Contains("mod = PZVoxelStudioViewpoint,")==selected,"selected models enabled while explicit opt-out excludes them");e.Switch(false,false);File.WriteAllText(e.Config,before);Directory.Move(Path.Combine(e.Workshop,"3619862853"),Path.Combine(root,"old-buddy"));bool failed=false;try{type.GetMethod("Enable").Invoke(null,new object[]{e,selected,new Func<ulong[],Dictionary<ulong,string>>(ids=>{throw new Exception("network fixture failure");})});}catch{failed=true;}Check(failed&&File.ReadAllText(e.Config)==before&&!File.Exists(Path.Combine(game,"zbNative.dll")),"failed dependency download leaves game installation unchanged");}
   var control=typeof(Engine).Assembly.GetType("PZ3D.GoldCheckBox");Check(control!=null,"checkbox has custom readable disabled rendering");using(var c=(CheckBox)Activator.CreateInstance(control)){c.Text="Readable";c.Size=new Size(180,32);c.Enabled=false;using(var bmp=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(bmp,c.ClientRectangle);int light=0;for(int y=0;y<bmp.Height;y++)for(int x=30;x<bmp.Width;x++){Color p=bmp.GetPixel(x,y);if(p.R>145&&p.G>145&&p.B>145)light++;}Check(light>20,"disabled checkbox text remains light on graphite background");}}
   string preferences=Path.Combine(LauncherTestPaths.Root,"orange-ui-preferences-"+Guid.NewGuid().ToString("N"));using(var form=new MainForm(preferences)){var checkbox=(CheckBox)typeof(MainForm).GetField("models",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(checkbox.Checked,"first-use model pack selected by default");checkbox.Checked=false;var actions=(Control)typeof(MainForm).GetField("buttons",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(actions.Controls.Count==3&&actions.Controls.Cast<Control>().All(c=>c is Button),"primary installation exposes only install uninstall and update actions");var tabs=form.Controls[0].Controls.OfType<TabControl>().Single();Check(!tabs.TabPages.Cast<TabPage>().Any(t=>t.Text=="射击客户端实验"),"shooting choice is on primary page rather than a separate confusing tab");Check(typeof(MainForm).GetField("chineseOption",BindingFlags.Instance|BindingFlags.NonPublic)!=null,"game-menu Chinese is selectable from primary installation");}using(var form=new MainForm(preferences)){var checkbox=(CheckBox)typeof(MainForm).GetField("models",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(!checkbox.Checked,"player opt-out remembered on reopening tool");}
  }
 }
}
